<#
.SYNOPSIS
    Reboots a remote Windows host via PSRemoting.
.DESCRIPTION
    Stand-alone script that creates a PowerShell remoting session to the target
    computer and issues a reboot command. No external helpers are required.
.PARAMETER ComputerName
    The name or IP address of the remote host to reboot.
.PARAMETER Credential
    Optional PSCredential object used for authentication.
.PARAMETER Force
    If specified, forces the reboot even if there are running processes.
.EXAMPLE
    .\Invoke-RemoteReboot.ps1 -ComputerName 'Server01'
.EXAMPLE
    .\Invoke-RemoteReboot.ps1 -ComputerName 'Server01' -Credential (Get-Credential) -Force
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true, Position = 0)]
    [string]$ComputerName,

    [Parameter(Mandatory = $false)]
    [System.Management.Automation.PSCredential]$Credential,

    [Parameter(Mandatory = $false)]
    [switch]$Force
)

$ErrorActionPreference = 'Stop'

function Test-RemoteHost {
    param(
        [string]$Name
    )
    if (-not (Test-Connection -ComputerName $Name -Count 1 -Quiet)) {
        throw "Unable to reach remote host '$Name'."
    }
}

function Invoke-RebootCommand {
    param(
        [string]$Target,
        [System.Management.Automation.PSCredential]$Cred,
        [switch]$ForceFlag
    )

    $sessionOptions = New-PSSessionOption -Authentication Negotiate

    if ($Cred) {
        $session = New-PSSession -ComputerName $Target -Credential $Cred -SessionOption $sessionOptions
    } else {
        $session = New-PSSession -ComputerName $Target -SessionOption $sessionOptions
    }

    try {
        if ($ForceFlag) {
            Invoke-Command -Session $session -ScriptBlock { Restart-Computer -Force }
        } else {
            Invoke-Command -Session $session -ScriptBlock { Restart-Computer }
        }
    } finally {
        Remove-PSSession -Session $session
    }
}

# Main execution
Test-RemoteHost -Name $ComputerName
Write-Verbose "Initiating reboot on '$ComputerName'..."
Invoke-RebootCommand -Target $ComputerName -Cred $Credential -ForceFlag:$Force
Write-Host "Reboot command sent to '$ComputerName'." -ForegroundColor Green
